mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p;
  q.z += time * 1.2;
  vec2 id = floor(q.xz / 1.0);
  q.xz = mod(q.xz, 1.0) - 0.5;
  float h = 1.2 + 0.7 * sin(id.x * 2.0 + id.y * 2.0 + time * 3.0) * bass;
  float spire = length(q.xz) - 0.09 * (1.0 - (p.y + 1.2) / (h + 1.2));
  spire = max(spire, -p.y - 1.2);
  spire = max(spire, p.y - h);
  return spire;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 2.2, -3.2);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.55) * rd.yz;
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 12.0) break;
    t += d * 0.8;
  }
  vec3 col = glow * vec3(0.1, 1.0, 0.6) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
